#[inline(never)]
pub fn fragment()->Fragment{
    let mut code=Vec::with_capacity(INSTRUCTION_COUNT);
    code.extend(instruction_group_00());
    code.extend(instruction_group_01());
    code.extend(instruction_group_02());
    code.extend(instruction_group_03());
    code.extend(instruction_group_04());
    code.extend(instruction_group_05());
    code.extend(instruction_group_06());
    Fragment{file_start:FILE_START,file_end:FILE_END,code}
}
#[cfg(test)] mod tests{
    use super::*;
    #[test]
    fn peripheral_firmware_instructions_are_adjacent(){
        let f=fragment();
        assert_eq!(f.code.len(),INSTRUCTION_COUNT);
        let b=super::super::extension6_disjoint::emit(&f).unwrap();
        assert_eq!(b.len(),FILE_END-FILE_START);
    }
}
